2:     path = require('path'),
3:     files = require('../lib/files'),
4:     scripts = require('../lib/scripts'),
5:     mversion = require('../'),
6:     thisVersion = require('../package.json').version,
7:     usage = require('cli-usage');
8: 
9: usage(path.resolve(__dirname, '../usage.md'));
10: 
11: var defaultMessage = "v%s";
12: 
13: module.exports = function (argv, loggers, processCallback) {
14:   if (typeof loggers === 'function' || !loggers) {
15:     processCallback = loggers;
16:     loggers = {};
17:   }
18:   var logger = loggers.logger || console.log.bind(console);
19:   var errorLogger = loggers.errorLogger || console.error.bind(console);
20: 
21:   var rc = files.getRC();
22: 
23:   processCallback = processCallback || function () { };
24: 
25:   var parsedArguments = require('minimist')(argv, {
26:     'string': ['t', 'tag'],
27:     'boolean': ['n']
28:   });
29: 
30:   if (argv.length === 0) {
31:     return get();
32:   }
33: 
34:   if (!rc.scripts || !rc.scripts.preupdate) {
35:     return update();
36:   }
37: 
38:   return scripts.run(
39:     rc.scripts.preupdate,
40:     scriptsCallback('preupdate', update)
41:   );
42: 
43:   function get() {
44:     mversion.get(function (err, data) {
45:       if (err) {
46:         errorLogger(chalk.red(err.message));
47:       }
48: 
49:       for(file in data) {
50:         if (data[file]) {
51:           logger(chalk.green(file) + ': ' + chalk.yellow(data[file]));
52:         }
53:       }
54: 
55:       processCallback(err);
56:     });
57:   }
58: 
59:   function update () {
60:     var updateOptions = rc || {};
61:     updateOptions.version = parsedArguments._[0];
62:     updateOptions.noPrefix = !!parsedArguments.n || parsedArguments.prefix === false || !!updateOptions.noPrefix;
63: 
64:     if (isArgumentPassed('v', 'version')) {
65:       logger('mversion v' + thisVersion);
66:       return processCallback();
67:     }
68: 
69:     // Check for git:
70:     if (isArgumentPassed('m')) {
71:       updateOptions.commitMessage =
72:         parsedArguments.m === true
73:           ? defaultMessage
74:           : parsedArguments.m;
75:     }
76: 
77:     // Check for overriding tag name
78:     if (isArgumentPassed('t', 'tag')) {
79:       updateOptions.tagName = parsedArguments.t || parsedArguments.tag;
80:     }
81: 
82:     if (updateOptions.commitMessage && rc.scripts && rc.scripts.precommit) {
83:       updateOptions.precommit = function (errorCb) {
84:         scripts.run(rc.scripts.precommit, scriptsCallback('precommit', errorCb));
85:       };
86:     }
87: 
88:     mversion.update(updateOptions, function (err, data) {
89:       if (err) {
90:         errorLogger(chalk.red('Failed updating:'));
91: 
92:         if (!data) {
93:           errorLogger(err.message);
94:         } else {
95:           errorLogger(constructError(
96:             err.message,
97:             data.updatedFiles,
98:             updateOptions.commitMessage,
99:             updateOptions.noPrefix,
100:             data.newVersion
101:           ));
102:         }
103:         return processCallback(err);
104:       }
105: 
106:       if (data && data.newVersion) {
107:         logger(chalk.green('Updated to new version: ') + chalk.yellow('v' + data.newVersion));
108:         logger(data.message);
109:       }
110: 
111:       if (!rc.scripts || (!rc.scripts.postcommit && !rc.scripts.postupdate)) {
112:         return processCallback();
113:       }
114: 
115:       if (rc.scripts.postcommit && updateOptions.commitMessage) {
116:         scripts.run(
117:           rc.scripts.postcommit.replace('%s', data.newVersion),
118:           scriptsCallback('postcommit', runPostUpdate)
119:         );
120:       }else{
121:         return runPostUpdate();
122:       }
123: 
124:       function runPostUpdate() {
125:         if (!rc.scripts.postupdate) return processCallback();
126:         scripts.run(
127:           rc.scripts.postupdate.replace('%s', data.newVersion),
128:           scriptsCallback('postupdate', processCallback)
129:         );
130:       }
131:     });
132:   }
133: 
134:   function isArgumentPassed () {
135:     var args = Array.prototype.slice.apply(arguments);
136:     for(var i = 0, len = args.length; i < len; i++) {
137:       if (!!parsedArguments[args[i]]) {
138:         return true;
139:       }
140:     }
141:     return false;
142:   }
143: 
144:   function scriptsCallback (scriptType, cb) {
145:     cb = cb || function () {};
146:     return function (err, stdout) {
147:       if (err) {
148:         errorLogger(chalk.red('Error running ' + scriptType + ':'), err.message);
149:         errorLogger(chalk.red('Stopping execution'));
150:         cb(err);
151:         return processCallback();
152:       }
153: 
