163: function constructError (errors, files, commitMessage, isNoPrefix, updatedVersion) {
164:   var commitFlag = commitMessage ? '-m "' + commitMessage + '"' : '';
165:   var noPrefixFlag = isNoPrefix ? '--no-prefix' : '';
166: 
167:   var ret = 'Some files contains errors:\n';
168: 
169:   ret += chalk.red(errors);
170: 
171:   if (files && files.length) {
172:     ret += '\n\nOther files (' + files.map(function (file) {
173:           return chalk.green(path.basename(file));
174:         }).join(', ') + ') got updated to version ' + chalk.yellow('v' + updatedVersion) + '.\n\n';
175:   }
176: 
177:   if (!!commitMessage) {
178:     ret += '\nThe changes were not commited, as there were errors.\n';
179:   }
180: 
181:   ret += 'Fix erros and try again to synchronize:\n';
182:   ret += chalk.bold(chalk.yellow(['$ mversion', updatedVersion, commitFlag, noPrefixFlag].join(' ')));
183:   return ret;
184: }

